Repository Pattern:
class NoteRepository(private val api: NoteApi, private val db: NoteDao) {
    fun getNotes(): Flow<Resource<List<Note>>> = flow {
        emit(Resource.Loading)
        // Emit cached data first
        val cached = db.getAllNotes()
        if (cached.isNotEmpty()) emit(Resource.Success(cached))
        // Fetch fresh data
        try {
            val remote = api.getNotes()
            db.insertAll(remote)
            emit(Resource.Success(remote))
        } catch (e: Exception) {
            if (cached.isEmpty()) emit(Resource.Error(e.message ?: "Offline"))
        }
    }.flowOn(Dispatchers.IO)
}

