Profiler & Memory Leaks:
// Common leak: anonymous inner class holds Activity reference
class MainActivity : AppCompatActivity() {
    private val handler = Handler(Looper.getMainLooper())

    fun startTimer() {
        handler.postDelayed({
            // this lambda holds reference to Activity — leaks if Activity finishes
            updateUI()
        }, 60000)
    }

    override fun onDestroy() {
        handler.removeCallbacksAndMessages(null)  // prevent leak
        super.onDestroy()
    }
}

// Better: lifecycle-aware handler
class MainActivity : AppCompatActivity() {
    // Use LifecycleObserver or coroutines instead
    private val scope = CoroutineScope(Dispatchers.Main + SupervisorJob())
    fun startTimer() {
        scope.launch {
            delay(60000)
            updateUI()
        }
    }
    override fun onDestroy() {
        scope.cancel()  // auto-cancels on destroy
        super.onDestroy()
    }
}

