// WebSocket
func connectWebSocket() {
    let session = URLSession.shared
    let ws = session.webSocketTask(with: URL(string: "wss://echo.example.com")!)
    ws.resume()

    // Send
    ws.send(.string("Hello")) { error in
        if let error = error { print(error) }
    }

    // Receive
    func receive() {
        ws.receive { result in
            switch result {
            case .success(let message):
                switch message {
                case .string(let text): print(text)
                default: break
                }
                receive()  // listen for next message
            case .failure(let error): print(error)
            }
        }
    }
    receive()
}

