// Retain cycle: closure captures self strongly
class NoteService {
    var onUpdate: (() -> Void)?

    func start() {
        // Retain cycle! self → onUpdate → self
        // Fix with [weak self]
        onUpdate = { [weak self] in
            guard let self else { return }
            self.refresh()
        }
    }

    func refresh() { }
}

// Delegate pattern: weak reference
protocol NoteDelegate: AnyObject {
    func noteDidUpdate(_ note: Note)
}

class NoteViewController: UIViewController {
    weak var delegate: NoteDelegate?  // avoid retain cycle
}

// unowned for guaranteed lifetime
class Parent {
    var child: Child?
}
class Child {
    unowned let parent: Parent  // parent always outlives child
    init(parent: Parent) { self.parent = parent }
}

