// Unowned — faster, assumes self outlives closure
func setupTimer() {
    Timer.scheduledTimer(withTimeInterval: 1.0, repeats: true) { [unowned self] timer in
        self.tick()  // crashes if self deallocated while timer fires
    }
}

// Practical: weak for async operations
class ImageLoader {
    func load(url: URL) async -> UIImage? {
        // Task captures self weakly automatically in async context
        guard let data = try? await URLSession.shared.data(from: url).0 else { return nil }
        return UIImage(data: data)
    }
}

